const llm = $input.first().json;

// Get actual PostgreSQL response directly
const dbResponse = $("HTTP Request").first().json;
const grievance = dbResponse.body ?? dbResponse;

if (!grievance.ticket_code) {
  throw new Error(
    "Ticket code missing. Check the HTTP Request response."
  );
}

// Extract Groq response
let raw = llm.text ?? llm.output ?? llm.response ?? "";

let ai = {};

if (typeof raw === "string" && raw.trim()) {
  raw = raw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start !== -1 && end > start) {
    try {
      ai = JSON.parse(raw.substring(start, end + 1));
    } catch {
      ai = {};
    }
  }
}

const updates = Array.isArray(grievance.updates)
  ? grievance.updates
  : [];

const latestUpdate = [...updates].sort(
  (a, b) =>
    new Date(b.created_at) - new Date(a.created_at)
)[0];

let nextAction = ai.next_action ||
  "Please contact the assigned department for assistance.";

if (!ai.next_action) {
  if (grievance.status === "Open") {
    nextAction = "Your grievance is awaiting review.";
  } else if (grievance.status === "In Progress") {
    nextAction = "The assigned department is reviewing your grievance.";
  } else if (grievance.status === "Resolved") {
    nextAction = "Please confirm whether your issue is resolved.";
  } else if (grievance.status === "Closed") {
    nextAction = "Contact the department if the issue persists.";
  }
}

return [{
  json: {
    agent: "followup",
    status: "success",
    ticket_code: grievance.ticket_code,
    registration_number: grievance.registration_number,
    student_name: grievance.student_name,
    subject: grievance.subject,
    current_status: grievance.status,
    assigned_department: grievance.assigned_department,
    latest_update: latestUpdate?.update_note ?? "No updates available.",
    response: ai.response ||
      `Your grievance ${grievance.ticket_code} is currently ${grievance.status}. Assigned department: ${grievance.assigned_department}.`,
    next_action: nextAction,
    needs_human_review:
      grievance.assigned_department === "Pending verification",
    updates
  }
}];
